css:
/* A GENERATED STRUCTURE, SET LIKE THE ONES AROUND IT.
   `.cst-name` (chem-structure) is the reference for the same job —
   caption under a drawing, slightly faded, book's own type. `.cring`
   just adds the ring drawing itself: RDKit's SVG, sized to sit on the
   baseline like `.sp` does, so a ring can appear inline in a sentence
   or centred in a `.dm` display line without special-casing either. */
.cring { display:inline-flex; flex-direction:column; align-items:center;
         vertical-align:middle; margin:0 5px; }
.cring svg { display:block; }
.cring-name { font-size:15px; line-height:1.2; opacity:.86;
              font-style:normal; margin-top:2px; text-align:center; }
.subj-chemistry .cring-name { font-size:15px; }
.acol .cring svg { width:78%; height:auto; max-width:100%; }
.cring { break-inside:avoid; }
